import json, math, random, statistics, sys

SUITE = ["perp", "mmlu", "hellaswag", "winogrande", "arc_c", "gsm8k", "humaneval"]
LOWER_IS_BETTER = {"perp": True}
MAIN_BENCHMARKS = [b for b in SUITE if b != "perp"]   # ppl = alignment-free PT probe, reported separately

def load_rows(src):
    if hasattr(src, "read"):
        obj = json.load(src)
    elif isinstance(src, str):
        with open(src) as fh:
            obj = json.load(fh)
    else:
        obj = src
    rows = obj["rows"] if isinstance(obj, dict) else obj
    return obj.get("meta", {}), list(rows)

def _mean(xs):
    return statistics.fmean(xs) if xs else float("nan")

def _std(xs):
    return statistics.stdev(xs) if len(xs) >= 2 else 0.0

def index(rows, key):
    out = {}
    for r in rows:
        out.setdefault(tuple(r[k] for k in key), []).append(r)
    return out

def per_benchmark_gaps(rows, cell, size70="70b", size13="13b"):
    grp = index(rows, ("cell", "size", "benchmark"))
    out = {}
    for b in SUITE:
        g70 = [r["score"] for r in grp.get((cell, size70, b), [])]
        g13 = [r["score"] for r in grp.get((cell, size13, b), [])]
        m70 = _mean(g70); m13 = _mean(g13)
        out[b] = {"m70": m70, "m13": m13, "gap": m70 - m13,
                  "sd13": _std(g13), "n13": len(g13), "n70": len(g70)}
    return out

def standardized_gap_terms(rows, cell):
    """Per-benchmark standardized gaps for within-cell 70B vs 13B.
    Standardized by 13B seed std (fallback |mean13|), sign-flipped for
    lower-is-better benchmarks so positive = 70B better everywhere."""
    per = per_benchmark_gaps(rows, cell)
    terms, details = [], {}
    for b, info in per.items():
        denom = info["sd13"] if info["sd13"] > 0 else (abs(info["m13"]) if abs(info["m13"]) > 0 else 1.0)
        g = info["gap"] / denom
        if LOWER_IS_BETTER.get(b):
            g = -g
        terms.append(g)
        details[b] = g
    return terms, details

def adversarial_gap_terms(rows, cell70, cell13):
    """Cross-cell adversarial comparison for the main H1 test:
    the larger model trained worse (cell70, deficient regime, its 70B arm)
    vs the smaller model trained well (cell13, adequate+refined, its 13B arm)."""
    per70 = per_benchmark_gaps(rows, cell70, size70="70b", size13="70b")
    per13 = per_benchmark_gaps(rows, cell13, size70="13b", size13="13b")
    terms = []
    for b in SUITE:
        m70 = per70[b]["m70"]; m13 = per13[b]["m13"]
        denom = per13[b]["sd13"] if per13[b]["sd13"] > 0 else (abs(m13) if abs(m13) > 0 else 1.0)
        g = (m70 - m13) / denom
        if LOWER_IS_BETTER.get(b):
            g = -g
        terms.append(g)
    return terms

def bootstrap_ci(samples, n_boot=5000, seed=1234, alpha=0.05):
    if not samples:
        return (float("nan"), float("nan"))
    rng = random.Random(seed)
    boots = []
    for _ in range(n_boot):
        boots.append(statistics.fmean(rng.choice(samples) for _ in range(len(samples))))
    boots.sort()
    lo = boots[max(0, int((alpha / 2) * (n_boot - 1)))]
    hi = boots[min(n_boot - 1, int((1 - alpha / 2) * (n_boot - 1)))]
    return (lo, hi)

def superiority_decision(terms, n_boot=5000, seed=1234):
    """Statistical claim: is 70B 'not necessarily superior' in this cell?
    negated = meanG <= 0 AND 95% CI upper bound <= 0."""
    mean_g = statistics.fmean(terms) if terms else float("nan")
    lo, hi = bootstrap_ci(terms, n_boot=n_boot, seed=seed)
    negated = (mean_g <= 0) and (hi <= 0)
