# ----------------------------------------------------------------------------
# linear model  score ~ alpha*size + beta*log(tok/param) + gamma*alignment
# ----------------------------------------------------------------------------

def design_matrix_and_y(rows, add_interaction=True):
    """Collapse to (cell, size, benchmark) means. Columns:
    [1, size70, log_tpp, align_base, align_sft, (size70 AND insufficient)]"""
    grp = index(rows, ("cell", "size", "benchmark"))
    X, y = [], []
    for (cell, size, bench), rs in sorted(grp.items()):
        sc = _mean([r["score"] for r in rs])
        tpp = _mean([r["tok_per_param"] for r in rs])
        align = rs[0]["align"]
        pt = rs[0]["pt_level"]
        row = [1.0,
               1.0 if size == "70b" else 0.0,
               math.log(tpp),
               1.0 if align == "base" else 0.0,
               1.0 if align == "sft" else 0.0,
               1.0 if (size == "70b" and pt == "insufficient") else 0.0]
        X.append(row); y.append(sc)
    return X, y

def _solve(A, b):
    n = len(A)
    for c in range(n):
        piv = max(range(c, n), key=lambda r: abs(A[r][c]))
        if piv != c:
            A[c], A[piv] = A[piv], A[c]; b[c], b[piv] = b[piv], b[c]
        pivv = A[c][c]
        A[c][c] = 1.0
        for j in range(n):
            A[c][j] /= pivv
        b[c] /= pivv
        for r in range(n):
            if r == c:
                continue
            fac = A[r][c]
            for j in range(c, n):
                A[r][j] -= fac * A[c][j]
            b[r] -= fac * b[c]
    return b

def fit_lm(X, y, ridge=1e-6):
    k = len(X[0]); n = len(X)
    A = [[0.0] * k for _ in range(k)]
    b = [0.0] * k
    for xi, yi in zip(X, y):
        for i in range(k):
            b[i] += xi[i] * yi
            for j in range(k):
                A[i][j] += xi[i] * xi[j]
    for i in range(k):
        A[i][i] += ridge
    return _solve(A, b)

def regression_report(rows):
    X, y = design_matrix_and_y(rows, add_interaction=True)
    coef = fit_lm(X, y)
    names = ["intercept", "size70(alpha)", "log_tpp(beta)", "align_base(gamma0)",
             "align_sft(gamma1)", "size70_x_insufficient(delta)"]
    report = dict(zip(names, coef))
    # ---- DERIVED negation boundary (estimate from fitted model; NOT assumed) ----
    alpha = coef[1]; beta = coef[2]; g_base = coef[3]; g_sft = coef[4]
    tpp13_good = 154.0   # 13B at 2T tokens (Llama-2 realized) = adequate reference arm
    tpp70_good = 28.6
    base_gap_same_regime = alpha + beta * (math.log(tpp70_good) - math.log(tpp13_good))
    tpp70_star = None
    if abs(beta) > 1e-12:
        tpp70_star = tpp13_good * math.exp(-alpha / beta)
    gap_base = alpha + beta * (math.log(tpp70_good) - math.log(tpp13_good)) + g_base
    gap_sft = alpha + beta * (math.log(tpp70_good) - math.log(tpp13_good)) + g_sft
    combined = {}
    for a, g_a in (("base", g_base), ("sft", g_sft), ("rlhf", 0.0)):
        combined[a] = tpp13_good * math.exp(-(alpha + g_a) / beta) if abs(beta) > 1e-12 else None
    report["negation_boundary"] = {
        "gap_13b_vs_70b_same_adequate_regime": base_gap_same_regime,
        "gap_70b_base_vs_13b_rlhf_adequatePT": gap_base,
        "gap_70b_sft_vs_13b_rlhf_adequatePT": gap_sft,
        "tpp70_star_adequate_alignment": tpp70_star,
        "tpp70_star_by_70B_alignment_level": combined,
    }
    return report

def bootstrap_boundary(rows, n_boot=2000, seed=7):
    grp = index(rows, ("cell", "size", "benchmark"))
    units = list(grp.items())
    rng = random.Random(seed)
    vals = []
    for _ in range(n_boot):
        sample = []
        for _k in range(len(units)):
            unit = rng.choice(units)[1]
            sample.extend(unit)
        try:
            v = regression_report(sample)["negation_boundary"]["tpp70_star_adequate_alignment"]
            if v is not None and math.isfinite(v) and v > 0:
                vals.append(v)
        except Exception:
            pass
    if not vals:
        return None
    vals.sort()
    return {"median": vals[len(vals) // 2],
            "ci": (vals[int(0.025 * (len(vals) - 1))], vals[int(0.975 * (len(vals) - 1))]),
            "n_fits": len(vals)}

# ----------------------------------------------------------------------------
# reporting
# ----------------------------------------------------------------------------

def summarize(rows, meta, adversarial=("insufficient_base", "adequate_rlhf")):
    cells = sorted(set(r["cell"] for r in rows))
    lines = [
        "NOTE: pure-Python analysis scaffold on a RESULTS TABLE. Loaded table = synthetic "
        "validation data unless stated otherwise; this is NOT an experiment result/outcome.",
        "",
        "## Per-cell paired size effect (positive meanG = 70B better)",
        "| cell | meanG | CI95 lo | CI95 hi | negated? | inv/bench |",
        "|---|---|---|---|---|---|",
    ]
    for c in cells:
        terms, det = standardized_gap_terms(rows, c)
        d = superiority_decision(terms)
        invb = ", ".join(b for b in MAIN_BENCHMARKS if det.get(b, 0) < 0) or "-"
        lines.append("| %s | %.3f | %.3f | %.3f | %s | %d/%d (%s) |" % (
            c, d["mean_g"], d["ci"][0], d["ci"][1], d["negated"],
            d["n_inverted"], d["n_benchmarks"], invb))
    lines.append("")
    lines.append("## Adversarial cross-cell comparison (main H1 test): %s(70B) vs %s(13B)" % adversarial)
    terms = adversarial_gap_terms(rows, adversarial[0], adversarial[1])
    d = superiority_decision(terms)
    lines.append("meanG=%.3f  CI95=(%.3f, %.3f)  negated=%s  inv=%d/%d benchmarks" % (
        d["mean_g"], d["ci"][0], d["ci"][1], d["negated"], d["n_inverted"], d["n_benchmarks"]))
    lines.append("")
    lines.append("## Linear model (score ~ size + log(tok/param) + alignment + interaction)")
    rep = regression_report(rows)
    for k, v in rep.items():
        if k == "negation_boundary":
            lines.append("- negation_boundary (DERIVED estimate, not assumed):")
            for k2, v2 in v.items():
                lines.append("    - %s = %s" % (k2, ("%.3f" % v2) if isinstance(v2, float) else v2))
        else:
            lines.append("- %s = %.4f" % (k, v))
    bci = bootstrap_boundary(rows)
    lines.append("- boundary uncertainty (refit bootstrap): %s" % (
        "none" if bci is None else
        "median tpp*=%.2f  CI95=(%.2f, %.2f)  (n=%d refits)" % (
            bci["median"], bci["ci"][0], bci["ci"][1], bci["n_fits"])))
    return "\n".join(lines)

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("usage: python3 analysis.py <results.json> [adv70cell] [adv13cell]")
        sys.exit(2)
    meta, rows = load_rows(sys.argv[1])
    adv = (sys.argv[2], sys.argv[3]) if len(sys.argv) >= 4 else ("insufficient_base", "adequate_rlhf")
    print(summarize(rows, meta, adv))
