"""synthetic_data.py -- generates SYNTHETIC validation tables for the analysis
scaffold. Two worlds:
  - 'h0': the world in which scale always wins (70B >= 13B in every cell and in
          the adversarial cross-cell comparison). Sanity: analysis must find NO
          negation anywhere.
  - 'h1': a world in which the 70B advantage persists within the same regime but
          INVERTS under the adversarial comparison (70B, insufficient pre-training
          + weak alignment vs 13B, adequate + refined). Sanity: analysis must
          detect the inversion in the adversarial cell and only there (and in
          similarly-deficient cells), while keeping the baseline cell positive.

These are NOT real measurements and NOT an experiment. They only exercise the
statistics pipeline (units, scales, signs, boundaries). Real tables must be
produced by external GPU evaluation and plugged in place of these files.
"""
import json, math, random

SUITE = ["perp", "mmlu", "hellaswag", "winogrande", "arc_c", "gsm8k", "humaneval"]
MAIN = [b for b in SUITE if b != "perp"]

# tokens-per-parameter per (pt_level, size)   [anchor values used in the design]
TPP = {
    ("adequate", "13b"): 154.0,      # 2T tokens (Llama-2 realized)
    ("adequate", "70b"): 28.6,       # 2T tokens (Llama-2 realized)
    ("insufficient", "13b"): 38.5,   # 500B tokens (pilot/degraded cell)
    ("insufficient", "70b"): 7.1,    # 500B tokens (~7 tok/param, far below Chinchilla-optimal ~20)
}

CELLS = [
    ("adequate_rlhf",  "adequate",   "rlhf"),
    ("adequate_sft",   "adequate",   "sft"),
    ("adequate_base",  "adequate",   "base"),
    ("insufficient_rlhf", "insufficient", "rlhf"),
    ("insufficient_sft",  "insufficient", "sft"),
    ("insufficient_base", "insufficient", "base"),
]

def make_world(kind="h1", n_seeds=8, seed=0):
    rng = random.Random(seed)
    # per-benchmark generative parameters (synthetic, realistic magnitudes)
    base13 = {"perp": 5.0, "mmlu": 0.55, "hellaswag": 0.79, "winogrande": 0.76,
              "arc_c": 0.52, "gsm8k": 0.35, "humaneval": 0.22}
    if kind == "h0":
        size_bonus = {"mmlu": 0.12, "hellaswag": 0.10, "winogrande": 0.10,
                      "arc_c": 0.09, "gsm8k": 0.14, "humaneval": 0.12}
        ppl_size = 0.70
    else:  # h1
        size_bonus = {"mmlu": 0.05, "hellaswag": 0.04, "winogrande": 0.04,
                      "arc_c": 0.04, "gsm8k": 0.08, "humaneval": 0.06}
        ppl_size = 0.50
    pt_slope = 0.015                       # effect per unit log(TPP) on accuracy
    sft_loss = 0.03                        # accuracy loss of SFT-only vs RLHF
    base_loss = 0.06                       # accuracy loss of base vs RLHF
    ppl_pt = 0.30                          # ppl improvement per unit log(TPP)
    ppl_sft_cost, ppl_rlhf_cost = 0.02, 0.04

    rows = []
    for cell, pt, align in CELLS:
        t13 = TPP[(pt, "13b")]; t70 = TPP[(pt, "70b")]
        for bench in SUITE:
            is_ppl = (bench == "perp")
            # mean signal for each arm (deterministic part)
            def mean_for(size):
                tpp = t13 if size == "13b" else t70
                ldiff = math.log(tpp) - math.log(154.0)
                if is_ppl:
                    base = base13["perp"] - (ppl_size if size == "70b" else 0.0) \
                           - ppl_pt * ldiff
                    if align == "sft": base += ppl_sft_cost
                    if align == "rlhf": base += ppl_rlhf_cost
                    return max(base, 1.0)
                s = base13[bench] + (size_bonus[bench] if size == "70b" else 0.0) \
                    + pt_slope * ldiff
                if align == "sft": s -= sft_loss
                if align == "base": s -= base_loss
                return min(max(s, 0.0), 1.0)
            noise_sd = 0.01 if is_ppl else 0.015
            for seed_id in range(n_seeds):
                for size in ("13b", "70b"):
                    m = mean_for(size) + rng.gauss(0, noise_sd)
                    if is_ppl:
                        m = max(m, 1.0)
                    else:
                        m = min(max(m, 0.0), 1.0)
                    rows.append({
                        "cell": cell, "size": size, "benchmark": bench,
                        "seed": seed_id, "score": round(m, 6),
                        "tok_per_param": t13 if size == "13b" else t70,
                        "align": align, "pt_level": pt,
                    })
    meta = {
        "kind": kind,
        "n_seeds": n_seeds,
        "suite": SUITE,
        "decoding": "synthetic (no real decoding; table only for scaffold validation)",
        "note": "SYNTHETIC VALIDATION DATA -- NOT an experiment result.",
    }
    return {"meta": meta, "rows": rows}

if __name__ == "__main__":
    for kind in ("h0", "h1"):
        obj = make_world(kind, seed=0)
        with open("/workspace/design/synthetic_%s.json" % kind, "w") as fh:
            json.dump(obj, fh, indent=1)
        print("wrote synthetic_%s.json with %d rows" % (kind, len(obj["rows"])))
