"""sanity_test.py -- runs the pure-Python analysis scaffold on SYNTHETIC tables
(no real experiment). Verifies the pipeline detects the intended structure:
  H0 world -> NO negation anywhere;
  H1 world -> baseline cell still shows 70B>13B, but the adversarial cross-cell
              comparison (70B insufficient-PT + weak alignment vs 13B adequate
              + refined) flips negative (negation detected).
This validates the statistics code, NOT any empirical claim.
"""
import json, sys
sys.path.insert(0, "/workspace/design")
import analysis as A
import synthetic_data as S

def run(kind):
    obj = S.make_world(kind, n_seeds=8, seed=0)
    fn = "/workspace/design/synthetic_%s.json" % kind
    with open(fn, "w") as fh:
        json.dump(obj, fh, indent=1)
    meta, rows = A.load_rows(fn)

    # within-cell decisions
    cells = sorted(set(r["cell"] for r in rows))
    negated_cells = []
    baseline_ci = None
    for c in cells:
        terms, _ = A.standardized_gap_terms(rows, c)
        d = A.superiority_decision(terms, n_boot=2000)
        if d["negated"]:
            negated_cells.append(c)
        if c == "adequate_rlhf":
            baseline_ci = d["ci"]

    # adversarial cross-cell (main H1 test)
    adv = A.adversarial_gap_terms(rows, "insufficient_base", "adequate_rlhf")
    adv_d = A.superiority_decision(adv, n_boot=2000)

    # regression + boundary
    rep = A.regression_report(rows)
    alpha, beta, g0, g1 = (rep["size70(alpha)"], rep["log_tpp(beta)"],
                           rep["align_base(gamma0)"], rep["align_sft(gamma1)"])
    tpp_star = rep["negation_boundary"]["tpp70_star_adequate_alignment"]

    print("  (%s) negated cells = %s ; baseline adequate_rlhf CI = %s ; adv negated = %s ; inv=%d/%d ; alpha=%.4f beta=%.4f gamma0=%.4f gamma1=%.4f tpp*=%.2f" % (
        kind, negated_cells or "none", tuple(round(v,3) for v in baseline_ci),
        adv_d["negated"], adv_d["n_inverted"], adv_d["n_benchmarks"],
        alpha, beta, g0, g1, tpp_star if tpp_star else -1.0))
    return dict(kind=kind, negated_cells=negated_cells, baseline_ci=baseline_ci,
                adv_negated=adv_d["negated"], alpha=alpha, beta=beta,
                g0=g0, g1=g1, tpp_star=tpp_star)

def main():
    print("NOTE: this sanity test runs the analysis scaffold on SYNTHETIC tables. It is NOT an experiment result.")
    h0 = run("h0")
    h1 = run("h1")
    ok = True
    # H0: nothing negated anywhere; baseline strictly positive
    assert not h0["negated_cells"], "H0 unexpectedly has negated within-cell comparisons"
    assert not h0["adv_negated"], "H0 unexpectedly negated in the adversarial comparison"
    assert h0["baseline_ci"][0] > 0, "H0 baseline CI should sit above zero"
    # H1: baseline still positive (size wins within adequate+refined regime)
    assert h1["baseline_ci"][0] > 0, "H1 baseline cell must keep 70B>13B"
    assert h1["adv_negated"], "H1 adversarial comparison must be detected as negated"
    assert len(h1["negated_cells"]) == 0, "H1 within-cell comparisons should stay non-negated (regime symmetric)"
    # coefficient signs must match the generative model
    assert h0["alpha"] > 0 and h1["alpha"] > 0, "size70 coefficient should be positive"
    assert h0["beta"] > 0 and h1["beta"] > 0, "log(tok/param) coefficient should be positive"
    assert h0["g0"] < 0 and h1["g0"] < 0, "align=base coefficient should be negative"
    assert h0["g1"] < 0 and h1["g1"] < 0, "align=sft coefficient should be negative"
    # boundary must be a finite positive derived estimate in H1
    assert h1["tpp_star"] and h1["tpp_star"] > 0, "H1 negation boundary should be a finite positive token/param value"
    print("SANITY TEST PASSED -- scaffold behaves as designed on synthetic worlds.")
    return 0 if ok else 1

if __name__ == "__main__":
    raise SystemExit(main())
